# MNSE Shell Adapter - Bash Integration
# Auto-generated by mnse-shell-adapter install-hooks --shell bash

__mnse_bash_start=0
__mnse_bash_cmd=""

__mnse_bash_preexec() {
    [ -n "$COMP_LINE" ] && return
    [ "$BASH_COMMAND" = "$PROMPT_COMMAND" ] && return
    __mnse_bash_start=$(date +%s%3N 2>/dev/null || echo 0)
    __mnse_bash_cmd="$BASH_COMMAND"
}

__mnse_bash_precmd() {
    local exit_code=$?
    if [ -n "$__mnse_bash_cmd" ]; then
        local now=$(date +%s%3N 2>/dev/null || echo 0)
        local duration=0
        if [ "$__mnse_bash_start" -gt 0 ]; then
            duration=$((now - __mnse_bash_start))
        fi
        mnse-shell-adapter record-exec --cmd "$__mnse_bash_cmd" --exit "$exit_code" --duration-ms "$duration" --cwd "$PWD" --session "$$" >/dev/null 2>&1 &
        __mnse_bash_cmd=""
    fi
}

trap '__mnse_bash_preexec' DEBUG
PROMPT_COMMAND="__mnse_bash_precmd;$PROMPT_COMMAND"
